  'Deload routine': 'Rutina de descarga',
  'Its workouts do not count toward progression. They still show in history and statistics.': 'Sus entrenamientos no cuentan para la progresión. Siguen apareciendo en el historial y las estadísticas.',
  'A deload routine opens at the numbers set here, so the progression above does not apply to it.': 'Una rutina de descarga empieza con los valores fijados aquí, así que la progresión de arriba no se le aplica.',
  'Linear progression': 'Progresión lineal',
  'Greyskull LP': 'Greyskull LP',
  'Double progression': 'Progresión doble',
  'Add time': 'Añadir tiempo',
  'Targets stay where you set them.': 'Los objetivos se quedan como los pongas.',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'Si completas todas las repeticiones de todas las series, sube el peso. Los fallos repetidos provocan una descarga.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'Dos series normales más una final al fallo. Si superas el objetivo en esa serie, sube el peso (el doble si doblas las repeticiones). Un fallo lo reduce un 10 %.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'Sube por un rango de repeticiones con el mismo peso. Alcanza el tope del rango en todas las series y el peso sube, con las repeticiones de vuelta al mínimo.',
  'Hold every set for the full duration and the target goes up.': 'Aguanta todas las series el tiempo completo y el objetivo sube.',
  'Nothing logged yet, so this session sets the baseline.': 'Aún no hay nada registrado, así que esta sesión marca el punto de partida.',
  'Held every set for the full time. Target goes up by {0}s.': 'Aguantaste todas las series el tiempo completo. El objetivo sube {0} s.',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': '{0} sesiones seguidas sin llegar. Baja a {1} s y vuelve a subir.',
  'Came up short last time. Same target again.': 'La última vez te quedaste corto. El mismo objetivo otra vez.',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'Tope del rango en todas las series. {0} {1} más, y vuelta a {2} repeticiones.',
  'Stuck for {0} sessions. Deload to {1} {2}.': 'Llevas {0} sesiones sin avanzar. Descarga a {1} {2}.',
  'Same weight, aim for {0} reps this time.': 'Mismo peso, esta vez apunta a {0} repeticiones.',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': '¡La última serie llegó a {0} repeticiones, el doble del objetivo! Sube el doble: {1} {2}.',
  'Every rep last time. {0} {1} more.': 'La última vez, todas las repeticiones. {0} {1} más.',
  'Every rep last time. {0} {1} less help.': 'La última vez, todas las repeticiones. {0} {1} menos de ayuda.',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': 'Tope del rango en todas las series. {0} {1} menos de ayuda, y vuelta a {2} repeticiones.',
  'Missed reps. {0} {1} of help while you build back up.': 'Repeticiones falladas. {0} {1} de ayuda mientras vuelves a subir.',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': 'Llevas {0} sesiones sin avanzar. Vuelve a {1} {2} de ayuda y sube otra vez.',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': '{0} sesiones seguidas fallando repeticiones. Vuelve a {1} {2} y sube de nuevo.',
  'Missed reps. Reset to {0} {1} and work back up.': 'Fallaste repeticiones. Vuelve a {0} {1} y sube de nuevo.',
  'Missed reps last time. Same weight again ({0} of {1} to go).': 'La última vez fallaste repeticiones. El mismo peso otra vez (quedan {0} de {1}).',
  'Bodyweight: every rep last time, so go for {0} this time.': 'Peso corporal: la última vez salieron todas las repeticiones, así que esta vez ve a por {0}.',
  'Bodyweight: same target again until every set is clean.': 'Peso corporal: el mismo objetivo hasta que todas las series salgan limpias.',

