  'Easy, warm-up territory': 'Fácil, zona de calentamiento',
  'Maybe half a rep left': 'Quizá media repetición más',
  'How hard was that set?': '¿Cómo de dura fue la serie?',
  'Tap how many reps you had left, or type an exact {0}.': 'Toca cuántas repeticiones te quedaban, o escribe un {0} exacto.',
  'Exact {0}': '{0} exacto',
  'Clear rating': 'Borrar valoración',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'El RIR cuenta las repeticiones que te quedan en reserva; el RPE lee ese mismo esfuerzo en una escala de 10, así que RPE ≈ 10 − RIR. Quédate con la que ya uses.',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': 'La fila resaltada es donde cae la mayoría de las series efectivas. Las series ya registradas conservan su escala, y nada más lee el valor, así que la progresión y el 1RM estimado no cambian.',
