  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': 'La mayoría de las series efectivas van cerca del fallo, no en él. La mitad abajo y la mitad arriba siguen dando una media que parece sana.',
  'Average effort per workout': 'Esfuerzo medio por entrenamiento',
  'A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.': 'Un punto más lleno significa menos reserva. El mismo peso con un {0} más bajo es progreso que la línea sola no muestra.',

