  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': 'Tu servidor ejecuta el entrenador con el proveedor que configuró su administrador. Nada nuevo sale de este teléfono más allá de lo que ya se sincroniza.',
