  // --- AI Coach chat ---
  'A local model can take longer.': 'Un modelo local puede tardar más.',
  'All optional. The more the Coach knows, the less it guesses.': 'Todo opcional. Cuanto más sepa el entrenador, menos tendrá que adivinar.',
