  'Discarded. Tell me what was off and I will build a different one.': 'Descartado. Dime qué no encajaba y haré otro distinto.',
  'Done! Your plan is back to how it was before my last changes.': '¡Hecho! Tu plan vuelve a estar como antes de mis últimos cambios.',
