  'Experience': 'Experiencia',
  'Goal, days, equipment, limits': 'Objetivo, días, equipamiento, límites',
  'Have a look at my training and tell me what you would change.': 'Mira mi entrenamiento y dime qué cambiarías.',
  'Here is what I am working with:': 'Esto es con lo que cuento:',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': 'Hola, soy tu entrenador. Construyo tu plan a partir de tus respuestas y lo ajusto según lo que realmente registras. Nada cambia hasta que tú lo digas.',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': 'Lo he revisado todo y ahora mismo no cambiaría nada. Sigue así y pregúntame de nuevo tras unas cuantas sesiones más.',
  'I understand, let’s go': 'Entendido, vamos',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': '¡Importado! {0} rutinas están en tu plan y tu semana ya está configurada. Nos vemos en la próxima sesión.',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': '¡Importado! {0} rutinas están en tu plan. Tu semana no cambia; prográmalas cuando quieras.',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': 'Diseña tu plan a partir de unas pocas respuestas y lo ajusta según lo que realmente registras. Nunca cambia nada sin tu permiso, y puedes deshacer cada cambio.',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': 'Rutinas, ejercicios, series y repeticiones, tu horario semanal y los ajustes de progresión.',
  'Your logged training': 'Tu entrenamiento registrado',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.': 'Las series que registraste en el periodo de revisión: pesos, repeticiones, tiempos, valoraciones de esfuerzo, cuánto duraron las sesiones y tus notas de las sesiones.',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'Los pesajes del mismo periodo y tu peso objetivo, si has fijado uno.',
