  'Some changes on this device have not reached your server.': 'Algunos cambios de este dispositivo aún no han llegado a tu servidor.',
  'Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Vuelve a intentarlo o exporta antes una copia. Si continúas de todos modos, se guarda una copia de estos cambios en este dispositivo hasta que vuelva a conectarse a este servidor con esta cuenta. Entonces se vuelven a añadir.',
