  'Editing a saved workout. Date and duration stay unchanged.': 'Estás editando un entrenamiento guardado. La fecha y la duración no cambian.',
  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': 'Un tirón por cada empuje, para que los hombros sigan equilibrados.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'Una rotación de dos días en tres sesiones por semana, construida con el equipamiento que indicaste. Primero los ejercicios compuestos, un tirón por cada empuje y suficiente solapamiento entre los días para que nada pase dos semanas sin entrenarse.',
  'Based on the training already in this demo profile.': 'Basado en el entrenamiento que ya hay en este perfil de demo.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'El peso corporal lleva cuatro semanas estancado y el objetivo es ganar. Eso es un problema de cocina, no de entrenamiento. No es el plan lo que lo frena.',
  'Demo': 'Demo',
  'Demo data reset': 'Datos de la demo restablecidos',
  'Direct arm work, since you asked for it.': 'Trabajo directo de brazos, ya que lo pediste.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Todas las series principales de este ejercicio quedaron en RPE 9,5 o más durante tres sesiones y el peso no se ha movido. Cambiar el movimiento durante cuatro semanas suele romper ese estancamiento antes que insistir en el mismo.',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Datos de ejemplo, guardados solo en este navegador. Trastea y cambia lo que quieras, sin miedo.',
  'Full body A': 'Cuerpo completo A',
  'Full body B': 'Cuerpo completo B',
  'Horizontal pressing, the other half of the session.': 'Empuje horizontal, la otra mitad de la sesión.',
  'Live demo. Everything stays in this browser.': 'Demo en vivo. Todo se queda en este navegador.',
  'No training history yet, so starting conservatively.': 'Aún no hay historial de entrenamiento, así que empezamos con prudencia.',
  'Passkey sign-in, sync across your devices, your own data.': 'Inicio de sesión con passkey, sincronización entre tus dispositivos, tus propios datos.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Devuelve el plan, los entrenamientos y los pesajes de ejemplo a como estaban al principio.',
  'Reset': 'Restablecer',
  'Reset demo data': 'Restablecer datos de la demo',
  'Reset demo data?': '¿Restablecer los datos de la demo?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Revisado como pediste. Todo lo que no cuestionaste queda exactamente como estaba.',
  'Same pattern, higher reps than day A.': 'El mismo patrón, más repeticiones que el día A.',
  'Self-host it in a minute →': 'Autoalójalo en un minuto →',
  'Self-host openGym': 'Autoalojar openGym',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Las sesiones se están alargando unos quince minutos. Este es el ejercicio accesorio que menos pierde con una serie menos.',
  'Start the demo': 'Iniciar la demo',
  'The main lower-body driver, where most of the strength comes from.': 'El motor principal del tren inferior, de donde sale la mayor parte de la fuerza.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Los mismos patrones, otras variantes: suficiente solapamiento para progresar, suficiente diferencia para no aburrirse.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Primero los dos grandes patrones de tren inferior y empuje, mientras estás fresco.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'Esta demo funciona por completo en tu navegador con datos de ejemplo. No se envía nada a ningún sitio. El inicio de sesión con passkey y la sincronización entre tus dispositivos llegan con el servidor de openGym, que consigues alojándolo tú mismo.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'Tres cosas que vale la pena cambiar y una que conviene saber. Todo lo demás funciona: la sentadilla y los tirones progresan según lo previsto.',
  'Vertical pressing.': 'Empuje vertical.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Has movido esta sesión al sábado tres semanas seguidas. Mejor que lo diga el plan a que tengas que cambiarlo cada vez.',
  'You’re in the demo': 'Estás en la demo',
