  'openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym ya no puede escribir en «{0}», así que las copias vuelven a Documents/openGym. Elige la carpeta otra vez para volver a usarla.',
  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym ya no puede escribir en la carpeta elegida, así que las copias vuelven a Documents/openGym. Elige la carpeta otra vez para volver a usarla.',
  // --- missed-workout nudge (lib/nudge.js; the push copy is mirrored in api/nudge-copy.js) ---
  'Nudge me when I skip a planned workout': 'Avísame cuando me salte un entrenamiento planificado',
  'Nudge tone': 'Tono del aviso',
  'Friendly': 'Amistoso',
  'Guilt trip': 'Chantaje emocional',
  'Drill sergeant': 'Sargento instructor',
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'Un aviso por la noche de un día planificado sin nada registrado, entre las 20:00 y las 21:30. Tras 3 días seguidos sin entrenar, se calla hasta tu próximo entrenamiento.',
  'Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.': '¿Entrenaste en otro dispositivo? Antes del aviso, el teléfono consulta a tu servidor siempre que deje a la app funcionar en segundo plano. Al abrir la app, todo se pone al día.',
  'Everything okay?': '¿Todo bien?',
  '{0} is still waiting. What’s up?': '{0} sigue esperando. ¿Qué pasa?',
  'No {0} today? Even a short session tomorrow counts.': '¿Hoy no hubo {0}? Mañana, hasta una sesión corta cuenta.',
  'Rough day? {0} will keep. Tomorrow is a fresh start.': '¿Día difícil? {0} puede esperar. Mañana empiezas de nuevo.',
  'Hey, {0} didn’t happen today. All good?': 'Oye, hoy no hubo {0}. ¿Todo bien?',
  'I miss you': 'Te echo de menos',
  '{0} waited by the door all evening. For you.': '{0} te esperó en la puerta toda la tarde. A ti.',
  'The barbell asked about you today. I didn’t know what to say.': 'La barra preguntó por ti hoy. No supe qué decirle.',
  'Was it something I said? {0} misses you.': '¿Fue algo que dije? {0} te echa de menos.',
  'I saved you a spot on the bench. It’s still empty.': 'Te guardé un sitio en el banco. Sigue vacío.',
  'Attention, recruit!': '¡Atención, recluta!',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': 'Tus ganancias están haciendo las maletas. ¡{0} mañana, sin excusas!',
  '{0} doesn’t do itself, recruit. Move it!': '{0} no se hace solo, recluta. ¡Muévete!',
  'Excuses don’t lift weights. Report for {0} tomorrow!': 'Las excusas no levantan pesas. ¡Mañana te presentas a {0}!',
  'Your muscles filed a missing-person report. Show up for {0}!': 'Tus músculos pusieron una denuncia por desaparición. ¡Preséntate a {0}!',
  'That address answers, but it isn’t an openGym server. Check the URL.': 'Esa dirección responde, pero no es un servidor de openGym. Revisa la URL.',
  'That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': 'Esa dirección responde, pero contestó una página de inicio de sesión o una regla del proxy en lugar de openGym. Deja pasar /api/ a openGym sin cambios. Mira “Phone app and CORS” en docs/SELF_HOSTING.md.',
  'Switch sides': 'Cambia de lado',
  'Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.': 'Guarda una copia con fecha en «{0}» al terminar un entreno o editar una rutina, y conserva las {1} más recientes.',
  'Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.': 'Guarda una copia con fecha en la carpeta que elegiste al terminar un entreno o editar una rutina, y conserva las {0} más recientes.',
