  'Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.': 'Tope del rango en las {0} series. {1} {2} más, de vuelta a {3} series de {4}.',
  'Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.': 'Tope del rango en las {0} series. {1} {2} menos de ayuda, de vuelta a {3} series de {4}.',
