  "Records": "Récords",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "Horario dice cuándo, Rutinas dice qué. Crea las tuyas o coge un plan de inicio.",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "Miles de ejercicios en tu idioma. Marca tus favoritos con estrella y suben arriba.",
  "See which muscles got the work and which still need rest. Tap one for details.": "Mira qué músculos trabajaron y cuáles aún necesitan descanso. Toca uno para ver detalles.",
