  "The big Start button": "El gran botón Empezar",
  "The little body shows what each day works, so leg day can’t hide.": "El cuerpito muestra qué trabaja cada día, así el día de pierna no se escapa.",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "El descanso empieza solo. Añade tiempo, o sáltalo si te sientes heroico.",
  "The ⋯ menu": "El menú ⋯",
  "Theme, accent colour and what Home shows.": "Tema, color de acento y lo que muestra Inicio.",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "Este es de mentira, no se guarda nada. Cada fila es una serie: peso y luego repeticiones. Toca un número para cambiarlo.",
  "Tick it off": "Márcala",
  "Today at a glance": "Hoy de un vistazo",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "Aquí está la sesión de hoy. Un toque y a levantar. En un día de descanso lo dice, sin culpa.",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "Entrena en días fijos o haz rotar tus rutinas en bucle: la siguiente te espera.",
  "Want a 1-minute tour?": "¿Un recorrido de 1 minuto?",
  "Week or rotation": "Semana o rotación",
