  // --- Settings → Integrations (1.4.4) ---
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "Esto vive en la app de openGym del móvil: Apple Health en iPhone, Health Connect en Android.",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "Los webhooks los envía tu propio servidor de openGym, así que hace falta uno. Conecta este dispositivo en Cuenta.",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "Los webhooks están desactivados en este servidor. Añade INTEGRATIONS=webhook a su .env y reinícialo.",
  "The MCP server runs next to your own openGym server and reads your data there.": "El servidor MCP funciona junto a tu propio servidor de openGym y lee tus datos allí.",
  "Only what you switch on talks to anything. The rest stays out of your way.": "Solo lo que actives habla con algo. El resto no te molesta.",
  "Could not reach your server": "No se pudo contactar con tu servidor",
  "Tap to try again": "Toca para intentarlo de nuevo",
  "Disconnect {0}?": "¿Desconectar {0}?",
