  "Hold the back of your phone to the sticker.": "Acerca la parte trasera del móvil a la pegatina.",
  "Hold the top of your iPhone near the sticker.": "Acerca la parte de arriba del iPhone a la pegatina.",
  "It isn’t in this workout yet.": "Todavía no está en este entreno.",
  "Just check in": "Solo registrar entrada",
  "NFC is off. Turn it on in your phone’s settings and try again.": "El NFC está apagado. Actívalo en los ajustes del móvil y vuelve a intentarlo.",
  "NFC sticker for this exercise": "Pegatina NFC para este ejercicio",
  "Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.": "Pégala en tu taquilla, tu bolsa o la puerta del gimnasio. Un toque con el móvil y listo.",
  "Set up an NFC sticker": "Configurar una pegatina NFC",
  "Shows your gym membership code, ready for the scanner.": "Muestra tu código de socio, listo para el lector.",
  "Start today’s workout": "Empezar el entreno de hoy",
  "Starts what’s planned for today, or opens the one already running.": "Empieza lo planeado para hoy, o abre el entreno en curso.",
  "Stick it on the machine. Tap it during a workout to jump to {0}, or to add it.": "Pégala en la máquina. Tócala durante un entreno para ir a {0}, o para añadirlo.",
  "Sticker ready.": "Pegatina lista.",
  "Sticker ready. Tap it with your phone to try it.": "Pegatina lista. Tócala con el móvil para probarla.",
  "Tap it at the gym to start your workout or show your code.": "Tócala en el gimnasio para empezar tu entreno o mostrar tu código.",
  "That didn’t work. Hold your phone still on the sticker and try again.": "No ha funcionado. Mantén el móvil quieto sobre la pegatina y vuelve a intentarlo.",
  "This sticker can’t hold a link. Try an NTAG sticker.": "Esta pegatina no puede guardar un enlace. Prueba con una NTAG.",
  "This sticker is for an exercise you don’t have.": "Esta pegatina es de un ejercicio que no tienes.",
  "This sticker is locked. Try a blank one.": "Esta pegatina está bloqueada. Prueba con una en blanco.",
  "This sticker is too small. NTAG213 or bigger works.": "Esta pegatina es demasiado pequeña. Sirve una NTAG213 o mayor.",
