  "Body": "Cuerpo",
  "Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.": "Se calculan con tu peso de trabajo y se redondean a los discos y mancuernas de este gimnasio. Cada ejercicio puede elegir los suyos en sus ajustes.",
  "Built from your work weight when the workout starts.": "Se calculan con tu peso de trabajo al empezar el entrenamiento.",
