  "Each one closes half the gap to the work weight.": "Cada una cierra la mitad de la distancia al peso de trabajo.",
  "Every loaded lift": "Cada ejercicio con carga",
  "Feeling great": "Me siento genial",
  "Follows Settings → Workout → Automatic warm-ups.": "Sigue Ajustes → Entrenamiento → Calentamientos automáticos.",
  "For this workout": "Para este entrenamiento",
  "Heavy lifts get more rungs, light ones one or none.": "Lo pesado tiene más escalones, lo ligero uno o ninguno.",
  "It hurts": "Me duele",
  "It hurts, it’s taken, no time, feeling great": "Duele, ocupado, sin tiempo, me siento genial",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "Molesta, así que más ligero lo que queda. Para si sigue doliendo.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "Molesta, así que las series que te quedan pasan a un movimiento que trabaja el mismo músculo desde un ángulo más amable.",
  "Keep these warm-ups": "Guardar estos calentamientos",
  "Kept. Same warm-ups next time, scaled to your work weight.": "Guardado. Los mismos calentamientos la próxima vez, ajustados a tu peso de trabajo.",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Las series registradas y tu rutina quedan como están. El Entrenador no es médico ni fisioterapeuta. Si algo te duele, consulta a un profesional.",
  "Looking at your workout…": "Mirando tu entrenamiento…",
  "Machine’s taken": "Máquina ocupada",
  "My own": "Los míos",
  "New programme “{0}”": "Nuevo programa «{0}»",
