  "Only the warm-ups you plan yourself.": "Solo los calentamientos que planificas tú.",
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": "Escalonado desde el peso de trabajo: más escalones si es pesado, menos si es ligero.",
