  "Short on time": "Poco tiempo",
  "Skip the rest of {0}": "Saltar lo que queda de {0}",
  "Something else": "Otra cosa",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "Sentadillas, presses, remos y compañía tienen subida. Curls y elevaciones empiezan en frío.",
  "Straight into the work sets.": "Directo a las series de trabajo.",
  "That workout is over, so these can’t be applied any more.": "Ese entrenamiento terminó, así que ya no se pueden aplicar.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "La app sube desde tu peso de trabajo: más calentamientos si es pesado, menos si es ligero, con los discos de tu gimnasio.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "El rack está ocupado, así que hazlo al final. El resto de la sesión no lo necesita.",
  "There’s no workout running.": "No hay ningún entrenamiento en curso.",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "Estos calentamientos van antes de las series de trabajo en cada sesión, como parte del peso de trabajo, así que crecen con él.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "Esto es la demo, así que no hay un modelo de IA detrás. En tu propio servidor leo tu sesión y sugiero cambios como estos.",
