  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Esto es público para todo el mundo en este servidor: cualquiera con una cuenta aquí puede verlo, probarlo y copiarlo. Tu nombre y la fecha van siempre con ello. Comparte solo lo que es tuyo: algo que hiciste, grabaste o tienes derecho a pasar. Las imágenes y animaciones de ejercicios de la biblioteca integrada tienen licencia y nunca se pueden compartir. Puedes dejar de compartir cuando quieras; las copias que otros ya tomaron se quedan con ellos.",
