  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Grasa corporal, masa magra, masa ósea, agua corporal y metabolismo basal, tal como los guardó tu báscula. Aparecen en Medidas corporales y nunca se mezclan con lo que registras.",
