  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "El cardio se sube como lo que fue: una carrera, una salida en bici, una sesión de remo. La fuerza como Entrenamiento con pesas, con cada serie en la descripción.",
