  "Same as the rest ({0})": "Igual que el resto ({0})",
  "Seconds for each part of a rep: lower, pause, lift, squeeze. 3-1-1-0 is three down, one at the bottom, one up, straight into the next.": "Segundos para cada parte de una repetición: bajar, pausa, subir, apretar. 3-1-1-0 son tres bajando, uno abajo, uno subiendo y directo a la siguiente.",
  "Show finished workouts too": "Mostrar también entrenamientos terminados",
  "Strava connected. Your next workout goes up by itself.": "Strava conectado. Tu próximo entrenamiento se sube solo.",
  "Strava disconnected": "Strava desconectado",
  "Strava is listening": "Strava está escuchando",
  "Strava is off on this server. Register a Strava API app, then add strava to INTEGRATIONS and its STRAVA_CLIENT_ID and STRAVA_CLIENT_SECRET to the .env, and restart.": "Strava está apagado en este servidor. Registra una app de la API de Strava, añade strava a INTEGRATIONS y su STRAVA_CLIENT_ID y STRAVA_CLIENT_SECRET al .env, y reinicia.",
  "Strava uploads come from your own openGym server, so they need one. Connect this device to it in Account.": "Las subidas a Strava salen de tu propio servidor openGym, así que necesitas uno. Conecta este dispositivo a él en Cuenta.",
  "Strength workouts too": "También los de fuerza",
  "Subscribe to this link in your calendar app. Anyone with it sees your plan, so keep it to yourself.": "Suscríbete a este enlace en tu app de calendario. Quien lo tenga ve tu plan, así que guárdatelo para ti.",
