  "Tempo {0}, start the guide": "Tempo {0}, iniciar la guía",
  "The calendar link is served by your own openGym server, so it needs one. Connect this device to it in Account.": "El enlace del calendario lo sirve tu propio servidor openGym, así que necesitas uno. Conecta este dispositivo a él en Cuenta.",
  "The link stops working at once. What your calendar already shows may stay until it refreshes.": "El enlace deja de funcionar al instante. Lo que tu calendario ya muestra puede quedarse hasta que se actualice.",
  "The old link stops working, and every calendar that uses it needs the new one.": "El enlace viejo deja de funcionar, y cada calendario que lo usa necesita el nuevo.",
  "The password stays on this device, in its secure storage. It is never synced or put in a backup.": "La contraseña se queda en este dispositivo, en su almacenamiento seguro. Nunca se sincroniza ni va en una copia.",
  "The server cannot show this link again. Make a new one.": "El servidor no puede volver a mostrar este enlace. Crea uno nuevo.",
  "This device stops backing up and forgets the password. The backups already in the folder stay there.": "Este dispositivo deja de hacer copias y olvida la contraseña. Las copias que ya están en la carpeta se quedan ahí.",
  "Tick the set": "Marcar la serie",
  "Turn off": "Apagar",
  "Turn off the calendar feed?": "¿Apagar el feed de calendario?",
  "Up as fast as you can. The guide gives it one quick second.": "Sube tan rápido como puedas. La guía le da un segundito.",
  "Uploading": "Subiendo",
