  "WebDAV backup": "Copia en WebDAV",
  "When the app is open, at most once a day, on this device.": "Con la app abierta, como mucho una vez al día, en este dispositivo.",
  "Your planned sessions in Apple Calendar, Google Calendar or Outlook, kept up to date. A private link only your calendar knows.": "Tus sesiones planificadas en Apple Calendar, Google Calendar u Outlook, siempre al día. Un enlace privado que solo conoce tu calendario.",
  "Your server forgets the sign-in and stops uploading. What is on Strava stays, and the Strava app keeps its access until you remove it on strava.com.": "Tu servidor olvida el inicio de sesión y deja de subir. Lo que hay en Strava se queda, y la app de Strava mantiene su acceso hasta que lo quites en strava.com.",
  "{0} s per rep, a guide in the workout counts it for you.": "{0} s por repetición, una guía en el entrenamiento los cuenta por ti.",
  "{0} s under tension": "{0} s bajo tensión",
  "{0} s under tension. Lovely and slow.": "{0} s bajo tensión. Bien lento y bonito.",
