  // --- promises-146: progression rules, shoulder heads and lats, bench, own media ---,
  "Steady double progression": "Doble progresión constante",
  "Undulating days": "Días ondulantes",
  "Shorter rests": "Descansos más cortos",
  "Work up a rep range one rep at a time. Every set has to hit the target before it moves, and at the top of the range the weight goes up.": "Sube por un rango de repeticiones de una en una. Todas las series tienen que llegar al objetivo antes de que suba, y arriba del rango sube el peso.",
  "Each session rotates: a medium day at your reps, a heavy day with fewer, a light day with more. The weights come from your estimated max, so they climb as you get stronger.": "Cada sesión rota: un día medio con tus repeticiones, un día pesado con menos y uno ligero con más. Los pesos salen de tu máximo estimado, así que suben cuando te haces más fuerte.",
  "Same weight, a bit less rest each time every set is clean. At your shortest rest the weight goes up and the rest starts over.": "Mismo peso, un poco menos de descanso cada vez que todas las series salen limpias. En tu descanso más corto sube el peso y el descanso empieza de nuevo.",
  "Every set hit {0}. Same weight, {1} reps this time.": "Todas las series llegaron a {0}. Mismo peso, {1} repeticiones esta vez.",
  "Not every set reached {0} yet. Same weight and target again ({1} of {2} to go).": "No todas las series llegaron a {0} todavía. Mismo peso y objetivo otra vez (quedan {1} de {2}).",
  "Every set clean. Same weight with {0}s less rest: {1}s.": "Todas las series limpias. Mismo peso con {0} s menos de descanso: {1} s.",
  "Clean at your shortest rest. {0} {1} less help, rest back to {2}s.": "Limpio con tu descanso más corto. {0} {1} menos de ayuda, descanso de vuelta a {2} s.",
  "Clean at your shortest rest. {0} {1} more, rest back to {2}s.": "Limpio con tu descanso más corto. {0} {1} más, descanso de vuelta a {2} s.",
  "Stuck for {0} sessions. Same weight with more rest: {1}s.": "Estancado {0} sesiones. Mismo peso con más descanso: {1} s.",
  "Missed reps last time. Same weight and rest again ({0} of {1} to go).": "Fallaste repeticiones la última vez. Mismo peso y descanso otra vez (quedan {0} de {1}).",
  "Heavy day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Día pesado: {0} repeticiones con {1} {2}, según tu máximo estimado de {3} {2}.",
  "Light day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Día ligero: {0} repeticiones con {1} {2}, según tu máximo estimado de {3} {2}.",
  "Medium day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Día medio: {0} repeticiones con {1} {2}, según tu máximo estimado de {3} {2}.",
