  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "Cuatro toques sobre sueño, energía, agujetas y estrés. En un mal día openGym te ofrece ir más suave, y tras unas semanas ves qué tienen en común tus días buenos.",
